/**
 * Small pictures in every form the concept-picture reader takes, made with Pillow (libjpeg-turbo, libwebp) from one drawn 40×24 image:
 * a gradient, two flat shapes with hard edges, a thin line. `rgba` is what Pillow itself decoded each file to (deflated, base64): the
 * oracle the readers are held to. None of them is anyone else's art.
 */
export const PICTURE_FIXTURES = {
  png_rgb: { width: 40, height: 24, file: "", rgba: "" },
  png_rgba: { width: 40, height: 24, file: "", rgba: "" },
  png_palette: { width: 40, height: 24, file: "", rgba: "" },
  png_16bit: { width: 40, height: 24, file: "", rgba: "" },
  jpeg_444: { width: 40, height: 24, file: "", rgba: "" },
  jpeg_420: { width: 40, height: 24, file: "", rgba: "" },
  jpeg_progressive: { width: 40, height: 24, file: "", rgba: "" },
  jpeg_gray: { width: 40, height: 24, file: "", rgba: "" },
  webp_lossless: { width: 40, height: 24, file: "", rgba: "" },
  webp_lossless_alpha: { width: 40, height: 24, file: "", rgba: "" },
  webp_lossy: { width: 40, height: 24, file: "", rgba: "" },
  webp_lossy_alpha: { width: 40, height: 24, file: "", rgba: "" },
} as const
